package org.slavicmyths.hellqa;
import java.util.*;import net.minecraft.core.*;import net.minecraft.gametest.framework.*;import net.minecraft.server.level.*;import net.minecraft.world.*;import net.minecraft.world.entity.*;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.nbt.*;import net.neoforged.neoforge.gametest.*;import org.slavicmyths.burningislands.*;import org.slavicmyths.losthalls.*;import org.slavicmyths.trophy.*;
@GameTestHolder("slavicmyths_hellqa") @PrefixGameTestTemplate(false)
public final class HellBossQaTests {
 static OceanTerrain.Plan chosenPlan(BlockPos home){return new OceanTerrain.Plan(home.getX(),home.getZ(),home.getY()-27);}
 @GameTest(template="empty") public static void manualPostenDimensionsAndPeaceful(GameTestHelper t){
  var server=t.getLevel().getServer();var old=server.getWorldData().getDifficulty();server.setDifficulty(Difficulty.NORMAL,true);
  try{for(var key:List.of(Level.OVERWORLD,Level.NETHER,Level.END)){var w=server.getLevel(key);var boss=PostenMob.TYPE.get().create(w);boss.setNoAi(true);boss.moveTo(0,90,0);w.addFreshEntity(boss);boss.tick();HellQaTests.check(!boss.isRemoved(),"Manual Posten disappeared in "+key.location());var tag=new CompoundTag();boss.addAdditionalSaveData(tag);HellQaTests.check(tag.getBoolean("PostenManual"),"Summoned Posten became natural");boss.discard();System.out.println("HELLQA_PASS manual Posten dimension="+key.location()+" seed="+w.getSeed()+" XYZ=0,90,0 survives initial tick; manual NBT");}
   var w=t.getLevel();var boss=IslandsContent.TYPES.get(IslandsContent.Kind.MAGMA_LORD).get().create(w);boss.moveTo(t.absoluteVec(new net.minecraft.world.phys.Vec3(3,2,3)));w.addFreshEntity(boss);var neutral=IslandsContent.TYPES.get(IslandsContent.Kind.HEAT_SALAMANDER).get().create(w);neutral.moveTo(boss.position().add(3,0,0));w.addFreshEntity(neutral);server.setDifficulty(Difficulty.PEACEFUL,true);boss.tick();neutral.tick();HellQaTests.check(boss.isRemoved()&&!neutral.isRemoved(),"Peaceful boss/neutral regression");neutral.discard();System.out.println("HELLQA_PASS real Peaceful removes magma lord and retains neutral salamander");
  }finally{server.setDifficulty(old,true);}t.succeed();
 }
 @GameTest(template="empty") public static void fourTrophyAnchorsAndRotation(GameTestHelper t){
  var w=t.getLevel();int i=0;for(var kind:List.of(TrophyHeads.Kind.GROVE_GUARDIAN,TrophyHeads.Kind.ZHARENITSA,TrophyHeads.Kind.POSTEN,TrophyHeads.Kind.MAGMA_LORD)){var p=t.absolutePos(new BlockPos(2+i*2,2,2));var block=TrophyHeads.BLOCKS.get(kind).get();var item=TrophyHeads.ITEMS.get(kind).get();HellQaTests.check(item instanceof net.minecraft.world.item.BlockItem,"No head blockitem "+kind);var state=block.defaultBlockState();w.setBlock(p,state,3);HellQaTests.check(w.getBlockEntity(p) instanceof TrophyHeadBlock.Tile,"Missing native trophy BE "+kind);for(var rot:Rotation.values()){var rotated=state.rotate(rot);w.setBlock(p,rotated,3);HellQaTests.check(!rotated.getShape(w,p).isEmpty(),"Empty trophy shape "+kind);}
   var loot=Block.getDrops(w.getBlockState(p),w,p,w.getBlockEntity(p));HellQaTests.check(loot.size()==1&&loot.getFirst().is(item)&&loot.getFirst().getCount()==1,"Missing/double head loot "+kind);w.removeBlock(p,false);i++;
  }System.out.println("HELLQA_PASS four real trophy BlockItems/BE/rotations/loot anchors; client rendering NOT_RUN");t.succeed();
 }
 @GameTest(template="empty",timeoutTicks=1200) public static void realNetherBiomeAndOceanChunk(GameTestHelper t){
  var w=t.getLevel().getServer().getLevel(Level.NETHER);var generator=w.getChunkSource().getGenerator();var state=w.getChunkSource().randomState();var source=generator.getBiomeSource();var sampler=state.sampler();Set<String> found=new java.util.TreeSet<>();Map<String,BlockPos> first=new HashMap<>();long start=System.nanoTime();
  for(int x=-4096;x<=4096;x+=256)for(int z=-4096;z<=4096;z+=256)for(int y:new int[]{36,64,100}){var b=source.getNoiseBiome(x>>2,y>>2,z>>2,sampler);String id=b.unwrapKey().orElseThrow().location().toString();found.add(id);first.putIfAbsent(id,new BlockPos(x,y,z));}
  for(String id:List.of("slavicmyths:navya_grove","slavicmyths:black_cinder","slavicmyths:lost_halls")){HellQaTests.check(found.contains(id),"Actual native biome source missing "+id+" in8192 window, seed="+w.getSeed()+" found="+found);var p=first.get(id);var chunk=w.getChunk(p);HellQaTests.check(chunk instanceof net.minecraft.world.level.chunk.LevelChunk,"Chunk did not generate "+id);System.out.println("HELLQA_WORLDGEN seed="+w.getSeed()+" biome="+id+" sampledXYZ="+p+" actualChunk="+chunk.getPos());}
  var ocean=IslandsWorldgen.context(w);OceanTerrain.Plan chosen=null;outer:for(int ring=0;ring<=12;ring++)for(int cx=-ring;cx<=ring;cx++)for(int cz=-ring;cz<=ring;cz++){if(Math.max(Math.abs(cx),Math.abs(cz))!=ring)continue;var plan=ocean.plan(cx*512+256,cz*512+256);if(ocean.region(plan)){chosen=plan;break outer;}}
  HellQaTests.check(chosen!=null,"No certified ocean region in bounded25x25 cells; seed="+w.getSeed());var p=chosen.home();var biome=source.getNoiseBiome(p.getX()>>2,p.getY()>>2,p.getZ()>>2,sampler);HellQaTests.check(biome.is(IslandsContent.BIOME),"Locate/native sampler disagrees with ocean mask");var chunk=w.getChunk(p);if(chunk.getAllReferences().values().stream().anyMatch(ref->!ref.isEmpty()))System.out.println("HELLQA_WORLDGEN_BLOCKED structure references at ocean centre "+p);else HellQaTests.check((w.getBlockState(p.below()).is(Blocks.BLACKSTONE)||w.getBlockState(p.below()).is(Blocks.BASALT)||w.getBlockState(p.below()).is(Blocks.OBSIDIAN))&&w.isEmptyBlock(p)&&w.isEmptyBlock(p.above()),"Real generated ocean arena floor/headroom missing at "+p+" floor="+w.getBlockState(p.below()));
  System.out.println("HELLQA_WORLDGEN seed="+w.getSeed()+" biome=slavicmyths:burning_islands home="+p+" found="+found+" nativeSamplingAnd4ChunksMs="+(System.nanoTime()-start)/1000000+"; diagnostic chunk requests, not survival");
  java.util.List<ChunkPos> forced=new ArrayList<>();int cx=p.getX()>>4,cz=p.getZ()>>4;for(int x=cx-3;x<=cx+3;x++)for(int z=cz-3;z<=cz+3;z++){w.getChunk(x,z);w.setChunkForced(x,z,true);forced.add(new ChunkPos(x,z));}
  // Production admits at most64 queued regions and retries4 every20t: allow one full320t round plus readiness margin.
  t.runAfterDelay(400,()->{try{
   for(int x=-24;x<=24;x++)for(int z=-24;z<=24;z++)if(x*x+z*z<=24*24){var q=p.offset(x,0,z);var floor=w.getBlockState(q.below());HellQaTests.check(floor.is(Blocks.BLACKSTONE)||floor.is(Blocks.BASALT)||floor.is(Blocks.OBSIDIAN),"Arena floor material "+q+" "+floor);for(int y=0;y<6;y++)HellQaTests.check(w.isEmptyBlock(q.above(y)),"Arena headroom blocked "+q.above(y));}
   var bosses=w.getEntitiesOfClass(IslandsMob.class,new net.minecraft.world.phys.AABB(p).inflate(64),e->e.kind==IslandsContent.Kind.MAGMA_LORD);if(bosses.isEmpty())try{var f=IslandsWorldgen.class.getDeclaredField("PENDING");f.setAccessible(true);int loaded=0,entity=0;for(var q:forced){if(w.hasChunk(q.x,q.z))loaded++;if(w.areEntitiesLoaded(q.toLong()))entity++;}System.out.println("HELLQA_CLEAN_BOSS_DIAGNOSTIC time="+w.getGameTime()+" loaded="+loaded+" entity="+entity+" pending="+f.get(null));// Diagnostic must never create the entity whose natural spawn this test asserts.
}catch(Exception e){System.out.println("HELLQA_DIAGNOSTIC_UNAVAILABLE "+e);}
   HellQaTests.check(bosses.size()==1,"Expected one natural boss after49 forced chunks before any terrain mutation, found "+bosses.size());System.out.println("HELLQA_PASS seed="+w.getSeed()+" full dry arena/6headroom and one chunk-event natural boss UUID="+bosses.getFirst().getUUID()+";49 artificial tickets, not normal player loading");
   var owner=new ServerPlayer(w.getServer(),w,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"TerrainFixture"),ClientInformation.createDefault());owner.connection=new HellQaTests.Listener(owner);owner.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);owner.setNoGravity(true);owner.moveTo(p.getX()+.5,p.getY(),p.getZ()+.5,0,0);var original=w.getBlockState(p.below());HellQaTests.check(TemporaryTerrain.magma(owner)&&w.getBlockState(p.below()).is(Blocks.MAGMA_BLOCK),"Worldgen provenance/temporary magma failed");
   t.runAfterDelay(130,()->{try{HellQaTests.check(w.getBlockState(p.below()).equals(original)&&!TemporaryTerrain.leased(w,p.below()),"Real scheduled magma expiry failed");System.out.println("HELLQA_PASS real120t magma TTL restored original native island floor");t.succeed();}finally{for(var q:forced)w.setChunkForced(q.x,q.z,false);}});
  }catch(Exception e){for(var q:forced)w.setChunkForced(q.x,q.z,false);throw e;}});

 }
}
